SELECT *
FROM users;
SELECT *
FROM orders
LIMIT 5;

SELECT 10.0/100 AS rate,
   (0.12-0.10)*100 AS percentage_points,
   (0.12-0.10)/0.10 AS relative_lift;

SELECT COUNT(*) AS all_rows,
   COUNT(DISTINCT user_id) AS users_with_orders
FROM orders;

SELECT user_id AS id,
   city AS user_city
FROM users;

SELECT user_id,
   COALESCE(city,'未知') AS city_label
FROM users;
SELECT 3.0 / NULLIF(0,0) AS safe_ratio;

SELECT DATE('2026-01-31 13:20:00') AS dt,
  DATE_ADD('2026-01-31',INTERVAL 1 DAY) AS next_day,
  DATEDIFF('2026-02-02','2026-01-31') AS day_gap,
  DATE_FORMAT('2026-01-31','%Y-%m') AS month;
SELECT CONCAT('user-',CAST(7 AS CHAR)) AS label,
  ROUND(100.0/3,2) AS amount;

SELECT *
FROM scratch;
START TRANSACTION;
UPDATE scratch SET amount=99
WHERE id=1;
SELECT *
FROM scratch;
ROLLBACK;
SELECT *
FROM scratch;
